#include "stdafx.h"#include "ControlBuilderSimpleFrame.h"#include "PrjView.h"#include "Resource.h"#include "ControlBuilderDoc.h"// KControlBuilderSimpleFrameIMPLEMENT_DYNCREATE(KControlBuilderSimpleFrame, CFrameWnd)KControlBuilderSimpleFrame::KControlBuilderSimpleFrame(): m_pDoc( NULL ){}KControlBuilderSimpleFrame::~KControlBuilderSimpleFrame(){}BEGIN_MESSAGE_MAP(KControlBuilderSimpleFrame, CFrameWnd)  ON_COMMAND(ID_DEVCTL_MOMSTATE, &KControlBuilderSimpleFrame::OnDevctlMomstate)  ON_WM_CREATE()END_MESSAGE_MAP()// KControlBuilderSimpleFrame message handlersBOOL KControlBuilderSimpleFrame::OnCreateClient(LPCREATESTRUCT lpcs, CCreateContext* pContext){  BOOL bCreateSpltr = m_wndSplitter.CreateStatic( this, 1, 2);  bCreateSpltr = m_wndSplitter.CreateView( 0, 0, RUNTIME_CLASS(KPrjView), CSize(230, 0), pContext );  bCreateSpltr = m_wndSplitter.CreateView( 0, 1, pContext->m_pNewViewClass, CSize(0, 0), pContext );  m_pDoc = (KControlBuilderDoc*)pContext->m_pCurrentDoc;  return bCreateSpltr;}void KControlBuilderSimpleFrame::OnDevctlMomstate(){  if( !m_pDoc || !m_pDoc->m_pcb )    return;  m_pDoc->m_pcb->EnableMomStateDEVCTL();}static UINT indicators[] ={  ID_SEPARATOR,};int KControlBuilderSimpleFrame::OnCreate(LPCREATESTRUCT lpCreateStruct){  if (CFrameWnd::OnCreate(lpCreateStruct) == -1)    return -1;  if (!m_wndStatusBar.Create(this) ||  !m_wndStatusBar.SetIndicators(indicators, _countof(indicators) ))  {    TRACE0("Failed to create status bar\n");    return -2;      // fail to create  }  return 0;}